    "zh-TW": "搜尋本地植物、樹木、草藥...",
    "es": "Buscar plantas locales, árboles, hierbas...",
    "ta": "உள்ளூர் தாவரங்கள், மரங்கள், மூலிகைகளைத் தேடுங்கள்...",
