    "gu": "સ્થાનિક છોડ, વૃક્ષો, જડીબુટ્ટીઓ શોધો...",
    "ml": "പ്രാദേശിക സസ്യങ്ങൾ, മരങ്ങൾ, ഔഷധസസ്യങ്ങൾ എന്നിവ തിരയുക...",
    "pa": "ਸਥਾਨਕ ਪੌਦਿਆਂ, ਰੁੱਖਾਂ, ਜੜ੍ਹੀਆਂ ਬੂਟੀਆਂ ਦੀ ਖੋਜ ਕਰੋ...",
    "or": "ସ୍ଥାନୀୟ ଉଦ୍ଭିଦ, ଗଛ, ହଳଦୀ ଖୋଜ ...",
    "sa": "स्थानीय वनस्पतयः, वृक्षाः, जडीबुटीः च अन्वेष्टुम्...",
    "as": "স্থানীয় উদ্ভিদ, গাছ, বনৌষধি অনুসন্ধান...",
    "ur": "مقامی پودے، درخت، جڑی بوٹیاں تلاش کریں...",
    "fr": "Recherchez des plantes, des arbres, des herbes locales...",
    "de": "Suchen Sie nach lokalen Pflanzen, Bäumen, Kräutern ...",
    "it": "Cerca piante, alberi, erbe locali...",
    "pt": "Pesquise plantas, árvores, ervas locais...",
    "ru": "Ищите местные растения, деревья, травы...",
    "ja": "地元の植物、木、ハーブを検索...",
    "ko": "지역 식물, 나무, 허브 검색...",
    "ar": "بحث النباتات المحلية والأشجار والأعشاب ...",
    "id": "Cari tanaman lokal, pohon, tumbuhan...",
    "tr": "Yerel bitkileri, ağaçları, bitkileri arayın...",
    "vi": "Tìm kiếm thực vật địa phương, cây cối, thảo dược...",
    "th": "ค้นหาพืชท้องถิ่น ต้นไม้ สมุนไพร...",
